-- DataPlus Academy: complete database for a NEW, EMPTY Supabase project.
--
-- Paste this whole file into Supabase Dashboard -> SQL Editor -> New query, and run it once.
-- It runs as a single transaction: if anything fails, nothing is kept.
-- It creates the tables, security rules (RLS), functions, the sign-up trigger,
-- the storage buckets and their rules, and turns on live updates for messages.
--
-- Do not run it on a database that is already in use. For an existing project,
-- apply new files from supabase/migrations one at a time instead.
--
-- Generated by scripts/build-supabase-setup.sh from supabase/migrations. Do not edit by hand.

BEGIN;

DO $guard$
BEGIN
  IF to_regclass('public.profiles') IS NOT NULL THEN
    RAISE EXCEPTION 'This project already has DataPlus tables. supabase/setup.sql is only for a new, empty project.';
  END IF;
  IF to_regclass('auth.users') IS NULL OR to_regclass('storage.buckets') IS NULL THEN
    RAISE EXCEPTION 'auth.users or storage.buckets is missing. Run this in the SQL Editor of a Supabase project.';
  END IF;
END
$guard$;


-- ===== Public schema =====

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

CREATE TYPE public.user_role AS ENUM (
    'student',
    'teacher',
    'admin'
);

CREATE FUNCTION public.add_teacher_as_group_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO public.group_members (group_chat_id, user_id, role)
  VALUES (NEW.id, NEW.teacher_id, 'admin');
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.admin_delete_course(p_course_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can delete courses';
  END IF;

  -- Delete the course (CASCADE will handle related data)
  DELETE FROM public.courses
  WHERE id = p_course_id;

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id)
  VALUES (auth.uid(), 'course_deleted_by_admin', 'course', p_course_id);

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.admin_delete_course(p_course_id uuid) IS 'Delete a course (admin only) - handles all related data via CASCADE';

CREATE FUNCTION public.approve_certificate(p_student_id uuid, p_course_id uuid, p_certificate_url text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_certificate_id UUID;
  v_admin_id UUID;
BEGIN
  v_admin_id := auth.uid();
  
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins can approve certificates';
  END IF;
  
  INSERT INTO public.certificates (
    student_id, course_id, certificate_url, status, approved_by, approved_at, notes, completion_date
  )
  VALUES (
    p_student_id, p_course_id, p_certificate_url, 'approved', v_admin_id, NOW(), p_notes,
    COALESCE((SELECT ce.completion_date FROM public.course_enrollments ce
     WHERE ce.student_id = p_student_id AND ce.course_id = p_course_id), NOW())
  )
  ON CONFLICT (student_id, course_id)
  DO UPDATE SET
    certificate_url = p_certificate_url,
    status = 'approved',
    approved_by = v_admin_id,
    approved_at = NOW(),
    notes = p_notes,
    updated_at = NOW()
  RETURNING id INTO v_certificate_id;
  
  RETURN v_certificate_id;
END;
$$;

CREATE FUNCTION public.approve_course_update(p_course_id uuid, p_review_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can approve course updates';
  END IF;

  -- Approve the course
  UPDATE public.courses
  SET 
    pending_update = false,
    approval_status = 'approved',
    last_approved_at = NOW(),
    update_notes = NULL
  WHERE id = p_course_id;

  -- Update history
  UPDATE public.course_update_history
  SET 
    status = 'approved',
    reviewed_by = auth.uid(),
    review_notes = p_review_notes,
    reviewed_at = NOW()
  WHERE course_id = p_course_id AND status = 'pending';

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id)
  VALUES (auth.uid(), 'course_update_approved', 'course', p_course_id);

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.approve_course_update(p_course_id uuid, p_review_notes text) IS 'Admins approve pending course updates';

CREATE FUNCTION public.approve_scholarship_application(p_application_id uuid, p_admin_id uuid, p_scholarship_level text DEFAULT 'partial'::text, p_discount_percent numeric DEFAULT 50, p_discount_fixed numeric DEFAULT NULL::numeric, p_admin_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app RECORD;
  v_code TEXT;
  v_coupon_id UUID;
  v_discount_type TEXT;
  v_discount_value NUMERIC;
  v_admin_id UUID;
BEGIN
  v_admin_id := auth.uid();
  IF v_admin_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  SELECT * INTO v_app FROM public.scholarship_applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found');
  END IF;

  IF v_app.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application already reviewed');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.courses c
    WHERE c.id = v_app.course_id
      AND c.scholarship_slots_max IS NOT NULL
      AND c.scholarship_slots_used >= c.scholarship_slots_max
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'No scholarship slots remaining');
  END IF;

  IF p_scholarship_level = 'full' OR COALESCE(p_discount_percent, 0) >= 100 THEN
    v_discount_type := 'percent';
    v_discount_value := 100;
  ELSIF p_scholarship_level = 'reduced' AND p_discount_fixed IS NOT NULL THEN
    v_discount_type := 'fixed';
    v_discount_value := p_discount_fixed;
  ELSE
    v_discount_type := 'percent';
    v_discount_value := COALESCE(p_discount_percent, 50);
  END IF;

  v_code := 'SCHOLAR-' || UPPER(SUBSTRING(REPLACE(gen_random_uuid()::TEXT, '-', ''), 1, 8));

  INSERT INTO public.coupons (
    code, description, discount_type, discount_value, currency,
    max_uses, max_uses_per_user, applies_to, course_id,
    coupon_type, is_active, created_by
  )
  SELECT
    v_code,
    'Scholarship for ' || c.title,
    v_discount_type,
    v_discount_value,
    COALESCE(c.currency, 'RWF'),
    1,
    1,
    'course',
    v_app.course_id,
    'scholarship',
    true,
    v_admin_id
  FROM public.courses c
  WHERE c.id = v_app.course_id
  RETURNING id INTO v_coupon_id;

  UPDATE public.scholarship_applications
  SET
    status = 'approved',
    scholarship_level = p_scholarship_level,
    discount_percent = CASE WHEN v_discount_type = 'percent' THEN v_discount_value ELSE NULL END,
    discount_fixed = CASE WHEN v_discount_type = 'fixed' THEN v_discount_value ELSE NULL END,
    coupon_id = v_coupon_id,
    generated_code = v_code,
    reviewed_by = v_admin_id,
    reviewed_at = now(),
    admin_notes = p_admin_notes,
    updated_at = now()
  WHERE id = p_application_id;

  UPDATE public.courses
  SET scholarship_slots_used = scholarship_slots_used + 1
  WHERE id = v_app.course_id;

  RETURN jsonb_build_object(
    'success', true,
    'code', v_code,
    'coupon_id', v_coupon_id,
    'discount_type', v_discount_type,
    'discount_value', v_discount_value
  );
END;
$$;

CREATE FUNCTION public.approve_teacher(p_teacher_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can approve teachers';
  END IF;

  -- Approve the teacher
  UPDATE public.profiles
  SET 
    teacher_approved = true,
    teacher_approval_status = 'approved',
    teacher_approval_date = NOW(),
    teacher_approved_by = auth.uid(),
    teacher_rejection_reason = NULL
  WHERE id = p_teacher_id AND role = 'teacher';

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id)
  VALUES (auth.uid(), 'teacher_approved', 'profile', p_teacher_id);

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.approve_teacher(p_teacher_id uuid) IS 'Approve a teacher account (admin only)';

CREATE FUNCTION public.calculate_chapter_progress(p_student_id uuid, p_chapter_id uuid) RETURNS TABLE(total_lessons integer, completed_lessons integer, progress_percentage numeric, all_completed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(cl.id)::INTEGER as total_lessons,
    COUNT(CASE WHEN slp.is_completed = true THEN 1 END)::INTEGER as completed_lessons,
    CASE 
      WHEN COUNT(cl.id) > 0 THEN 
        ROUND((COUNT(CASE WHEN slp.is_completed = true THEN 1 END)::NUMERIC / COUNT(cl.id)::NUMERIC) * 100, 2)
      ELSE 0
    END as progress_percentage,
    CASE
      WHEN COUNT(cl.id) > 0 AND COUNT(cl.id) = COUNT(CASE WHEN slp.is_completed = true THEN 1 END) THEN true
      ELSE false
    END as all_completed
  FROM public.course_lessons cl
  LEFT JOIN public.student_lesson_progress slp ON slp.lesson_id = cl.id AND slp.student_id = p_student_id
  WHERE cl.chapter_id = p_chapter_id;
END;
$$;

CREATE FUNCTION public.calculate_course_progress(p_student_id uuid, p_course_id uuid) RETURNS TABLE(total_lessons integer, completed_lessons integer, progress_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(cl.id)::INTEGER as total_lessons,
    COUNT(CASE WHEN slp.is_completed = true THEN 1 END)::INTEGER as completed_lessons,
    CASE 
      WHEN COUNT(cl.id) > 0 THEN 
        ROUND((COUNT(CASE WHEN slp.is_completed = true THEN 1 END)::NUMERIC / COUNT(cl.id)::NUMERIC) * 100, 2)
      ELSE 0
    END as progress_percentage
  FROM public.course_chapters ch
  JOIN public.course_lessons cl ON cl.chapter_id = ch.id
  LEFT JOIN public.student_lesson_progress slp ON slp.lesson_id = cl.id AND slp.student_id = p_student_id
  WHERE ch.course_id = p_course_id;
END;
$$;

CREATE FUNCTION public.can_access_lesson(p_lesson_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.course_lessons l
    JOIN public.course_chapters ch ON ch.id = l.chapter_id
    JOIN public.courses c ON c.id = ch.course_id
    WHERE l.id = p_lesson_id
      AND (
        c.is_free IS NOT FALSE
        OR coalesce(l.is_preview, false)
        OR coalesce(ch.is_preview, false)
        OR c.teacher_id = auth.uid()
        OR EXISTS (SELECT 1 FROM public.course_enrollments e
                   WHERE e.course_id = c.id AND e.student_id = auth.uid())
        OR EXISTS (SELECT 1 FROM public.profiles p
                   WHERE p.id = auth.uid() AND p.role = 'admin')
        OR public.is_course_facilitator(c.id)
      )
  );
$$;

CREATE FUNCTION public.can_create_course() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN public.get_user_role(auth.uid()) IN ('teacher', 'admin');
END;
$$;

COMMENT ON FUNCTION public.can_create_course() IS 'Check if user can create courses (teacher or admin)';

CREATE FUNCTION public.can_enroll_in_course() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN public.get_user_role(auth.uid()) IN ('student', 'admin');
END;
$$;

COMMENT ON FUNCTION public.can_enroll_in_course() IS 'Check if user can enroll in courses (student or admin)';

CREATE FUNCTION public.can_manage_lesson_file(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_dirs text[] := storage.foldername(p_name);
  v_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;
  IF public.is_admin(v_uid) THEN
    RETURN true;
  END IF;
  IF v_dirs[1] = 'capstone-submissions' THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.courses c
    WHERE c.teacher_id = v_uid AND (
      (coalesce(v_dirs[1], '') ~ v_uuid AND c.id = v_dirs[1]::uuid)
      OR EXISTS (SELECT 1 FROM public.course_chapters ch JOIN public.course_lessons l ON l.chapter_id = ch.id
                 WHERE ch.course_id = c.id
                   AND (public.lesson_file_ref_matches(l.file_url, p_name) OR public.lesson_file_ref_matches(l.content_url, p_name)))
      OR EXISTS (SELECT 1 FROM public.course_materials m
                 WHERE m.course_id = c.id AND public.lesson_file_ref_matches(m.file_url, p_name))
    )
  );
END;
$_$;

CREATE FUNCTION public.can_read_lesson_file(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_dirs text[] := storage.foldername(p_name);
  v_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF v_uid IS NOT NULL AND public.is_admin(v_uid) THEN
    RETURN true;
  END IF;

  -- Student work: capstone-submissions/<capstone or lesson id>/<student id>/<file>
  IF v_dirs[1] = 'capstone-submissions' THEN
    IF v_uid IS NULL THEN
      RETURN false;
    END IF;
    IF v_dirs[3] = v_uid::text OR v_dirs[2] = v_uid::text THEN
      RETURN true;
    END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.capstone_projects p JOIN public.courses c ON c.id = p.course_id
      WHERE c.teacher_id = v_uid AND (
        (coalesce(v_dirs[2], '') ~ v_uuid AND p.id = v_dirs[2]::uuid)
        OR EXISTS (SELECT 1 FROM public.capstone_submissions s
                   WHERE s.capstone_project_id = p.id AND public.lesson_file_ref_matches(s.file_url, p_name))
      )
    ) OR EXISTS (
      SELECT 1 FROM public.course_lessons l
      JOIN public.course_chapters ch ON ch.id = l.chapter_id
      JOIN public.courses c ON c.id = ch.course_id
      WHERE c.teacher_id = v_uid AND coalesce(v_dirs[2], '') ~ v_uuid AND l.id = v_dirs[2]::uuid
    );
  END IF;

  -- Course material: a lesson that uses the file (or <course id>/<lesson id>/<file>).
  IF EXISTS (
    SELECT 1 FROM public.course_lessons l
    WHERE (public.lesson_file_ref_matches(l.file_url, p_name)
           OR public.lesson_file_ref_matches(l.content_url, p_name)
           OR (coalesce(v_dirs[2], '') ~ v_uuid AND l.id = v_dirs[2]::uuid))
      AND public.can_access_lesson(l.id)
  ) THEN
    RETURN true;
  END IF;

  IF v_uid IS NULL THEN
    RETURN false;
  END IF;

  -- Course-wide files (materials, capstone briefs) for enrolled learners and the course's teacher,
  -- and everything in a teacher's own course folder.
  RETURN EXISTS (
    SELECT 1 FROM public.courses c
    WHERE (c.teacher_id = v_uid
           OR EXISTS (SELECT 1 FROM public.course_enrollments e WHERE e.course_id = c.id AND e.student_id = v_uid))
      AND (
        EXISTS (SELECT 1 FROM public.course_materials m
                WHERE m.course_id = c.id AND public.lesson_file_ref_matches(m.file_url, p_name))
        OR EXISTS (SELECT 1 FROM public.capstone_projects p
                   WHERE p.course_id = c.id AND public.lesson_file_ref_matches(p.file_url, p_name))
        OR (c.teacher_id = v_uid AND coalesce(v_dirs[1], '') ~ v_uuid AND c.id = v_dirs[1]::uuid)
      )
  );
END;
$_$;

CREATE FUNCTION public.can_review_submission(p_type text, p_submission_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.submission_owner(p_type, p_submission_id) o
                 WHERE public.facilitates_learner(o.course_id, o.student_id));
$$;

CREATE FUNCTION public.certificates_assign_identifiers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'approved' THEN
    IF NEW.certificate_number IS NULL THEN
      NEW.certificate_number := public.next_certificate_number();
    END IF;
    IF NEW.verification_code IS NULL THEN
      NEW.verification_code := public.new_verification_code();
    END IF;
    IF NEW.issued_at IS NULL THEN
      NEW.issued_at := coalesce(NEW.approved_at, now());
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    -- Identifiers never change once assigned.
    IF OLD.certificate_number IS NOT NULL THEN NEW.certificate_number := OLD.certificate_number; END IF;
    IF OLD.verification_code IS NOT NULL THEN NEW.verification_code := OLD.verification_code; END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.check_course_access(p_user_id uuid, p_course_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_free BOOLEAN;
  v_is_enrolled BOOLEAN;
  v_is_teacher BOOLEAN;
  v_is_admin BOOLEAN;
BEGIN
  -- Check if course is free
  SELECT COALESCE(is_free, true) INTO v_is_free
  FROM public.courses
  WHERE id = p_course_id;

  IF v_is_free THEN
    RETURN true;
  END IF;

  -- Check if user is the teacher of this course
  SELECT EXISTS(
    SELECT 1 FROM public.courses
    WHERE id = p_course_id AND teacher_id = p_user_id
  ) INTO v_is_teacher;

  IF v_is_teacher THEN
    RETURN true;
  END IF;

  -- Check if user is admin
  SELECT EXISTS(
    SELECT 1 FROM public.profiles
    WHERE id = p_user_id AND role = 'admin'
  ) INTO v_is_admin;

  IF v_is_admin THEN
    RETURN true;
  END IF;

  -- Check if user is enrolled
  SELECT EXISTS(
    SELECT 1 FROM public.course_enrollments
    WHERE student_id = p_user_id AND course_id = p_course_id
  ) INTO v_is_enrolled;

  RETURN v_is_enrolled;
END;
$$;

CREATE FUNCTION public.competition_can_submit(p_competition_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.competitions c
    JOIN public.competition_registrations r ON r.competition_id = c.id AND r.user_id = p_user_id AND r.status = 'registered'
    WHERE c.id = p_competition_id
      AND c.status = 'open'
      AND (c.starts_at IS NULL OR c.starts_at <= now())
      AND (c.submission_deadline IS NULL OR c.submission_deadline > now())
  );
$$;

CREATE FUNCTION public.competition_registration_open(p_competition_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.competitions c
    WHERE c.id = p_competition_id
      AND c.status IN ('upcoming', 'open')
      AND (c.registration_opens_at IS NULL OR c.registration_opens_at <= now())
      AND (c.registration_closes_at IS NULL OR c.registration_closes_at > now())
  );
$$;

CREATE FUNCTION public.course_of_capstone(p_capstone_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT course_id FROM public.capstone_projects WHERE id = p_capstone_id;
$$;

CREATE FUNCTION public.course_of_lesson(p_lesson_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ch.course_id FROM public.course_lessons l JOIN public.course_chapters ch ON ch.id = l.chapter_id WHERE l.id = p_lesson_id;
$$;

CREATE FUNCTION public.create_instalment_enrollment(p_student_id uuid, p_course_id uuid, p_total_amount numeric, p_currency text DEFAULT 'RWF'::text, p_cohort_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan RECORD;
  v_enrollment_id UUID;
  v_deposit NUMERIC;
  v_remainder NUMERIC;
  v_per_instalment NUMERIC;
  v_i INT;
BEGIN
  SELECT * INTO v_plan
  FROM public.course_instalment_plans
  WHERE course_id = p_course_id AND is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No instalment plan for this course');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.student_instalment_enrollments
    WHERE student_id = p_student_id AND course_id = p_course_id AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Active instalment plan already exists');
  END IF;

  v_deposit := ROUND(p_total_amount * v_plan.deposit_percent / 100, 0);
  v_remainder := p_total_amount - v_deposit;
  v_per_instalment := ROUND(v_remainder / (v_plan.instalment_count - 1), 0);

  INSERT INTO public.student_instalment_enrollments (
    student_id, course_id, plan_id, cohort_id, total_amount, currency, status
  ) VALUES (
    p_student_id, p_course_id, v_plan.id, p_cohort_id, p_total_amount, p_currency, 'active'
  )
  RETURNING id INTO v_enrollment_id;

  INSERT INTO public.instalment_schedules (enrollment_id, instalment_number, amount, due_date, status)
  VALUES (v_enrollment_id, 1, v_deposit, CURRENT_DATE, 'pending');

  FOR v_i IN 2..v_plan.instalment_count LOOP
    INSERT INTO public.instalment_schedules (enrollment_id, instalment_number, amount, due_date, status)
    VALUES (
      v_enrollment_id,
      v_i,
      CASE WHEN v_i = v_plan.instalment_count THEN v_remainder - (v_per_instalment * (v_plan.instalment_count - 2)) ELSE v_per_instalment END,
      (CURRENT_DATE + ((v_i - 1) * INTERVAL '30 days'))::DATE,
      'pending'
    );
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'enrollment_id', v_enrollment_id,
    'deposit_amount', v_deposit,
    'instalment_count', v_plan.instalment_count
  );
END;
$$;

