CREATE FUNCTION public.facilitates_learner(p_course_id uuid, p_student_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.course_staff s
    WHERE s.course_id = p_course_id AND s.user_id = p_user_id
      AND (
        s.cohort_id IS NULL
        OR EXISTS (
          SELECT 1 FROM public.course_enrollments e
          JOIN public.cohorts co ON co.id = s.cohort_id
          WHERE e.course_id = p_course_id AND e.student_id = p_student_id
            AND (e.cohort_id = s.cohort_id OR (e.cohort_id IS NULL AND e.cohort_name = co.name))
        )
      )
  );
$$;

CREATE FUNCTION public.facilitator_can_read_file(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_dirs text[] := storage.foldername(p_name);
  v_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_course uuid;
BEGIN
  IF auth.uid() IS NULL OR v_dirs[1] IS DISTINCT FROM 'capstone-submissions'
     OR coalesce(v_dirs[2], '') !~ v_uuid OR coalesce(v_dirs[3], '') !~ v_uuid THEN
    RETURN false;
  END IF;
  v_course := coalesce(public.course_of_capstone(v_dirs[2]::uuid), public.course_of_lesson(v_dirs[2]::uuid));
  RETURN v_course IS NOT NULL AND public.facilitates_learner(v_course, v_dirs[3]::uuid);
END;
$_$;

CREATE FUNCTION public.find_staffing_candidate(p_email text) RETURNS TABLE(id uuid, full_name text, role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.courses WHERE teacher_id = auth.uid())) THEN
    RAISE EXCEPTION 'Only instructors and administrators can assign facilitators' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT p.id, p.full_name, p.role::text FROM public.profiles p
    WHERE lower(p.email) = lower(btrim(p_email)) AND p.role::text <> 'admin' AND coalesce(p.is_suspended, false) = false
    LIMIT 1;
END;
$$;

CREATE FUNCTION public.get_activity_logs(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, user_id uuid, action text, entity_type text, entity_id uuid, details jsonb, ip_address text, user_agent text, created_at timestamp with time zone, user_full_name text, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if caller is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT 
    l.id,
    l.user_id,
    l.action,
    l.entity_type,
    l.entity_id,
    l.details,
    l.ip_address,
    l.user_agent,
    l.created_at,
    p.full_name as user_full_name,
    p.email as user_email
  FROM public.activity_logs l
  LEFT JOIN public.profiles p ON l.user_id = p.id
  ORDER BY l.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;

COMMENT ON FUNCTION public.get_activity_logs(p_limit integer, p_offset integer) IS 'Get activity logs for admin users only';

CREATE FUNCTION public.get_admin_dashboard_stats() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
  total_users INT;
  total_students INT;
  total_teachers INT;
  pending_teachers INT;
  total_courses INT;
  pending_courses INT;
  suspended_users INT;
  online_students INT;
  online_teachers INT;
  online_users INT;
  active_week INT;
BEGIN
  -- Total counts by role
  SELECT COUNT(*) INTO total_users FROM profiles;
  SELECT COUNT(*) INTO total_students FROM profiles WHERE role = 'student';
  SELECT COUNT(*) INTO total_teachers FROM profiles WHERE role = 'teacher';
  
  -- Pending teacher approvals
  SELECT COUNT(*) INTO pending_teachers 
  FROM profiles 
  WHERE role = 'teacher' AND teacher_approval_status = 'pending';
  
  -- Suspended users
  SELECT COUNT(*) INTO suspended_users 
  FROM profiles 
  WHERE is_suspended = true;
  
  -- Course counts
  SELECT COUNT(*) INTO total_courses FROM courses;
  SELECT COUNT(*) INTO pending_courses 
  FROM courses 
  WHERE approval_status = 'pending';
  
  -- Online users (active in last 5 minutes based on last_activity)
  SELECT COUNT(*) INTO online_students 
  FROM profiles 
  WHERE role = 'student' 
    AND last_activity >= NOW() - INTERVAL '5 minutes';
  
  SELECT COUNT(*) INTO online_teachers 
  FROM profiles 
  WHERE role = 'teacher' 
    AND last_activity >= NOW() - INTERVAL '5 minutes';
  
  online_users := online_students + online_teachers;
  
  -- Active users this week (based on last_activity)
  SELECT COUNT(*) INTO active_week 
  FROM profiles 
  WHERE last_activity >= NOW() - INTERVAL '7 days';
  
  -- Build result JSON
  result := json_build_object(
    'totalUsers', total_users,
    'totalStudents', total_students,
    'totalTeachers', total_teachers,
    'pendingTeachers', pending_teachers,
    'totalCourses', total_courses,
    'pendingCourses', pending_courses,
    'suspendedUsers', suspended_users,
    'onlineStudents', online_students,
    'onlineTeachers', online_teachers,
    'onlineUsers', online_users,
    'activeThisWeek', active_week
  );
  
  RETURN result;
END;
$$;

CREATE FUNCTION public.get_all_profiles() RETURNS TABLE(id uuid, email text, full_name text, role text, avatar_url text, phone text, pricing_tier text, created_at timestamp with time zone, updated_at timestamp with time zone, teacher_approved boolean, teacher_approval_status text, is_suspended boolean, suspension_reason text, last_login timestamp with time zone, last_activity timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.email,
    p.full_name,
    p.role::TEXT,
    p.avatar_url,
    p.phone,
    p.pricing_tier,
    p.created_at,
    p.updated_at,
    p.teacher_approved,
    p.teacher_approval_status,
    p.is_suspended,
    p.suspension_reason,
    p.last_login,
    p.last_activity
  FROM public.profiles p;
END;
$$;

CREATE FUNCTION public.get_all_student_progress() RETURNS TABLE(student_id uuid, student_name text, student_email text, student_phone text, course_id uuid, course_title text, teacher_name text, enrolled_at timestamp with time zone, total_lessons bigint, completed_lessons bigint, progress_percentage integer, last_activity timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT 
    p.id AS student_id,
    p.full_name AS student_name,
    p.email AS student_email,
    p.phone AS student_phone,
    c.id AS course_id,
    c.title AS course_title,
    t.full_name AS teacher_name,
    ce.created_at AS enrolled_at,
    COALESCE((SELECT COUNT(*) FROM lessons l WHERE l.course_id = c.id), 0) AS total_lessons,
    COALESCE((SELECT COUNT(*) FROM lesson_progress lp 
              JOIN lessons l ON l.id = lp.lesson_id 
              WHERE lp.user_id = p.id AND l.course_id = c.id AND lp.completed = true), 0) AS completed_lessons,
    CASE 
      WHEN (SELECT COUNT(*) FROM lessons l WHERE l.course_id = c.id) = 0 THEN 0
      ELSE ROUND(
        (COALESCE((SELECT COUNT(*) FROM lesson_progress lp 
                   JOIN lessons l ON l.id = lp.lesson_id 
                   WHERE lp.user_id = p.id AND l.course_id = c.id AND lp.completed = true), 0)::NUMERIC / 
         (SELECT COUNT(*) FROM lessons l WHERE l.course_id = c.id)::NUMERIC) * 100
      )::INT
    END AS progress_percentage,
    (SELECT MAX(lp.updated_at) FROM lesson_progress lp 
     JOIN lessons l ON l.id = lp.lesson_id 
     WHERE lp.user_id = p.id AND l.course_id = c.id) AS last_activity
  FROM profiles p
  JOIN course_enrollments ce ON ce.student_id = p.id
  JOIN courses c ON c.id = ce.course_id
  LEFT JOIN profiles t ON t.id = c.teacher_id
  WHERE p.role = 'student';
END;
$$;

CREATE FUNCTION public.get_competition_leaderboard(p_competition_id uuid) RETURNS TABLE(rank bigint, display_name text, score numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH best AS (
    SELECT s.user_id, max(s.score) AS score
    FROM public.competition_submissions s
    JOIN public.competitions c ON c.id = s.competition_id
    WHERE s.competition_id = p_competition_id
      AND s.status = 'scored' AND s.score IS NOT NULL
      AND c.results_published_at IS NOT NULL AND c.results_published_at <= now()
    GROUP BY s.user_id
  )
  SELECT rank() OVER (ORDER BY b.score DESC),
         coalesce(split_part(btrim(p.full_name), ' ', 1) || coalesce(' ' || left(nullif(split_part(btrim(p.full_name), ' ', 2), ''), 1) || '.', ''), 'Participant'),
         b.score
  FROM best b JOIN public.profiles p ON p.id = b.user_id
  ORDER BY b.score DESC
  LIMIT 100;
$$;

CREATE FUNCTION public.get_coupon_redemption_stats() RETURNS TABLE(coupon_id uuid, code text, coupon_type text, discount_type text, discount_value numeric, max_uses integer, uses_count integer, redemption_count bigint, total_discount numeric, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.code,
    c.coupon_type,
    c.discount_type,
    c.discount_value,
    c.max_uses,
    c.uses_count,
    COUNT(cr.id),
    COALESCE(SUM(cr.discount_amount), 0),
    c.is_active
  FROM public.coupons c
  LEFT JOIN public.coupon_redemptions cr ON cr.coupon_id = c.id
  GROUP BY c.id
  ORDER BY COUNT(cr.id) DESC, c.code;
END;
$$;

CREATE FUNCTION public.get_course_approvals() RETURNS TABLE(id uuid, course_id uuid, status text, reviewed_by uuid, review_notes text, created_at timestamp with time zone, reviewed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if caller is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  -- Check if table exists
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'course_approvals') THEN
    RAISE EXCEPTION 'Course approvals table does not exist.';
  END IF;

  RETURN QUERY
  SELECT 
    ca.id,
    ca.course_id,
    ca.status,
    ca.reviewed_by,
    ca.review_notes,
    ca.created_at,
    ca.reviewed_at
  FROM public.course_approvals ca;
END;
$$;

COMMENT ON FUNCTION public.get_course_approvals() IS 'Get course approvals for admin users only';

CREATE FUNCTION public.get_course_completions(p_course_id uuid DEFAULT NULL::uuid) RETURNS TABLE(enrollment_id uuid, student_id uuid, student_name text, student_email text, course_id uuid, course_title text, teacher_name text, completed boolean, completion_date timestamp with time zone, final_grade text, progress_percentage integer, certificate_id uuid, certificate_status text, certificate_url text, certificate_approved_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH course_lesson_counts AS (
    -- Count total lessons per course
    SELECT 
      ch.course_id,
      COUNT(cl.id) AS total_lessons
    FROM public.course_chapters ch
    INNER JOIN public.course_lessons cl ON cl.chapter_id = ch.id
    GROUP BY ch.course_id
  ),
  student_completed_lessons AS (
    -- Count completed lessons per student per course
    SELECT 
      slp.student_id,
      ch.course_id,
      COUNT(slp.lesson_id) AS completed_lessons,
      MAX(slp.completed_at) AS last_completed_at
    FROM public.student_lesson_progress slp
    INNER JOIN public.course_lessons cl ON cl.id = slp.lesson_id
    INNER JOIN public.course_chapters ch ON ch.id = cl.chapter_id
    WHERE slp.is_completed = TRUE
    GROUP BY slp.student_id, ch.course_id
  )
  SELECT 
    ce.id AS enrollment_id,
    ce.student_id,
    p.full_name::TEXT AS student_name,
    u.email::TEXT AS student_email,
    ce.course_id,
    c.title::TEXT AS course_title,
    tp.full_name::TEXT AS teacher_name,
    TRUE AS completed,
    scl.last_completed_at AS completion_date,
    ce.final_grade::TEXT,
    100 AS progress_percentage,
    cert.id AS certificate_id,
    cert.status::TEXT AS certificate_status,
    cert.certificate_url::TEXT,
    cert.approved_at AS certificate_approved_at
  FROM public.course_enrollments ce
  INNER JOIN public.profiles p ON ce.student_id = p.id
  INNER JOIN auth.users u ON ce.student_id = u.id
  INNER JOIN public.courses c ON ce.course_id = c.id
  INNER JOIN public.profiles tp ON c.teacher_id = tp.id
  INNER JOIN course_lesson_counts clc ON clc.course_id = ce.course_id
  INNER JOIN student_completed_lessons scl ON scl.student_id = ce.student_id AND scl.course_id = ce.course_id
  LEFT JOIN public.certificates cert ON cert.student_id = ce.student_id AND cert.course_id = ce.course_id
  WHERE 
    scl.completed_lessons >= clc.total_lessons
    AND clc.total_lessons > 0
    AND (p_course_id IS NULL OR ce.course_id = p_course_id)
  ORDER BY scl.last_completed_at DESC;
END;
$$;

CREATE FUNCTION public.get_course_staff(p_course_id uuid) RETURNS TABLE(id uuid, user_id uuid, cohort_id uuid, full_name text, email text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.courses c WHERE c.id = p_course_id AND c.teacher_id = auth.uid())) THEN
    RAISE EXCEPTION 'Only the course instructor and administrators can list its facilitators' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT s.id, s.user_id, s.cohort_id, p.full_name, p.email, s.created_at
    FROM public.course_staff s JOIN public.profiles p ON p.id = s.user_id
    WHERE s.course_id = p_course_id ORDER BY p.full_name;
END;
$$;

CREATE FUNCTION public.get_facilitated_learners() RETURNS TABLE(course_id uuid, student_id uuid, full_name text, avatar_url text, cohort_name text, progress_percentage numeric, completed boolean, last_activity_at timestamp with time zone, enrolled_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.course_id, e.student_id, p.full_name, p.avatar_url, e.cohort_name,
         e.progress_percentage::numeric, coalesce(e.completed, false), e.last_activity_at, e.enrolled_at
  FROM public.course_enrollments e
  JOIN public.profiles p ON p.id = e.student_id
  WHERE public.facilitates_learner(e.course_id, e.student_id)
  ORDER BY p.full_name;
$$;

CREATE FUNCTION public.get_instalment_tracker() RETURNS TABLE(enrollment_id uuid, student_id uuid, student_name text, student_email text, course_id uuid, course_title text, total_amount numeric, currency text, status text, paid_count bigint, pending_count bigint, overdue_count bigint, next_due_date date, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT
    e.id,
    e.student_id,
    p.full_name,
    p.email,
    e.course_id,
    c.title,
    e.total_amount,
    e.currency,
    e.status,
    COUNT(*) FILTER (WHERE s.status = 'paid'),
    COUNT(*) FILTER (WHERE s.status = 'pending'),
    COUNT(*) FILTER (WHERE s.status = 'overdue'),
    MIN(s.due_date) FILTER (WHERE s.status IN ('pending', 'overdue')),
    e.created_at
  FROM public.student_instalment_enrollments e
  JOIN public.profiles p ON p.id = e.student_id
  JOIN public.courses c ON c.id = e.course_id
  LEFT JOIN public.instalment_schedules s ON s.enrollment_id = e.id
  GROUP BY e.id, p.full_name, p.email, c.title
  ORDER BY e.created_at DESC;
END;
$$;

CREATE FUNCTION public.get_lesson_quiz(p_lesson_id uuid) RETURNS TABLE(id uuid, question_text text, options jsonb, points integer, order_index integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_access_lesson(p_lesson_id) THEN
    RAISE EXCEPTION 'You do not have access to this quiz' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT q.id, q.question_text, q.options, coalesce(q.points, 1), q.order_index
    FROM public.lesson_quiz_questions q
    WHERE q.lesson_id = p_lesson_id
    ORDER BY q.order_index, q.created_at;
END;
$$;

CREATE FUNCTION public.get_lesson_quiz_review(p_lesson_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a record;
  v_review jsonb;
BEGIN
  SELECT * INTO a FROM public.student_quiz_attempts
  WHERE student_id = auth.uid() AND lesson_id = p_lesson_id
  ORDER BY submitted_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'question_id', q.id,
           'selected', a.answers->>(q.id::text),
           'correct_answer', q.correct_answer,
           'is_correct', (a.answers->>(q.id::text) = q.correct_answer),
           'explanation', q.explanation) ORDER BY q.order_index, q.created_at), '[]'::jsonb)
    INTO v_review
  FROM public.lesson_quiz_questions q WHERE q.lesson_id = p_lesson_id;
  RETURN jsonb_build_object(
    'attempt_id', a.id, 'score', a.score, 'total_points', a.total_points,
    'passed', a.passed, 'submitted_at', a.submitted_at, 'review', v_review
  );
END;
$$;

CREATE FUNCTION public.get_onboarding_insights() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min constant integer := 5;
  v_result jsonb;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only administrators can read onboarding insights' USING ERRCODE = '42501';
  END IF;

  WITH consenting AS (
    SELECT * FROM public.learner_preferences WHERE research_consent
  ),
  answers AS (
    SELECT 'goal' AS question, learning_goal AS answer FROM consenting WHERE learning_goal IS NOT NULL
    UNION ALL SELECT 'level', experience_level FROM consenting WHERE experience_level IS NOT NULL
    UNION ALL SELECT 'mode', preferred_mode FROM consenting WHERE preferred_mode IS NOT NULL
    UNION ALL SELECT 'hours', weekly_hours FROM consenting WHERE weekly_hours IS NOT NULL
    UNION ALL SELECT 'access', access_route FROM consenting
    UNION ALL SELECT 'interest', unnest(interests) FROM consenting
    UNION ALL SELECT 'tool', unnest(tools) FROM consenting
  ),
  counted AS (
    SELECT question, answer, count(*)::integer AS n FROM answers GROUP BY question, answer
  ),
  grouped AS (
    SELECT question,
      coalesce(jsonb_object_agg(answer, n) FILTER (WHERE n >= v_min), '{}'::jsonb) AS shown,
      coalesce(sum(n) FILTER (WHERE n < v_min), 0)::integer AS suppressed
    FROM counted GROUP BY question
  )
  SELECT jsonb_build_object(
    'minimum_group_size', v_min,
    'learners_with_answers', (SELECT count(*) FROM public.learner_preferences),
    'consenting_learners', (SELECT count(*) FROM consenting),
    'questions', coalesce((SELECT jsonb_object_agg(question, jsonb_build_object('counts', shown, 'suppressed', suppressed)) FROM grouped), '{}'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;

CREATE FUNCTION public.get_pending_course_updates() RETURNS TABLE(course_id uuid, course_title text, teacher_id uuid, teacher_name text, update_submitted_at timestamp with time zone, update_notes text, thumbnail_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can view pending course updates';
  END IF;

  RETURN QUERY
  SELECT 
    c.id as course_id,
    c.title as course_title,
    c.teacher_id,
    p.full_name as teacher_name,
    c.update_submitted_at,
    c.update_notes,
    c.thumbnail_url
  FROM public.courses c
  JOIN public.profiles p ON c.teacher_id = p.id
  WHERE c.pending_update = true
  ORDER BY c.update_submitted_at DESC;
END;
$$;

COMMENT ON FUNCTION public.get_pending_course_updates() IS 'Get all courses with pending updates';

CREATE FUNCTION public.get_student_pending_instalments(p_student_id uuid DEFAULT auth.uid()) RETURNS TABLE(schedule_id uuid, enrollment_id uuid, course_id uuid, course_title text, instalment_number integer, amount numeric, currency text, due_date date, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_student_id IS DISTINCT FROM auth.uid()
     AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    s.id,
    e.id,
    e.course_id,
    c.title,
    s.instalment_number,
    s.amount,
    e.currency,
    s.due_date,
    s.status
  FROM public.instalment_schedules s
  JOIN public.student_instalment_enrollments e ON e.id = s.enrollment_id
  JOIN public.courses c ON c.id = e.course_id
  WHERE e.student_id = p_student_id
    AND e.status = 'active'
    AND s.status IN ('pending', 'overdue')
  ORDER BY s.due_date, s.instalment_number;
END;
$$;

CREATE FUNCTION public.get_system_settings() RETURNS TABLE(id uuid, key text, value jsonb, description text, updated_by uuid, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if caller is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied. Admin privileges required.';
  END IF;

  RETURN QUERY
  SELECT 
    s.id,
    s.key,
    s.value,
    s.description,
    s.updated_by,
    s.updated_at
  FROM public.system_settings s;
END;
$$;

COMMENT ON FUNCTION public.get_system_settings() IS 'Get system settings for admin users only';

CREATE FUNCTION public.get_unread_announcements_count() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_count INTEGER;
BEGIN
  v_user_id := auth.uid();
  
  SELECT role INTO v_role FROM public.profiles WHERE id = v_user_id;
  
  SELECT COUNT(*) INTO v_count
  FROM public.announcements a
  WHERE a.is_active = TRUE
    AND (a.expires_at IS NULL OR a.expires_at > NOW())
    AND (
      a.target_audience = 'all'
      OR (a.target_audience = 'students' AND v_role = 'student')
      OR (a.target_audience = 'teachers' AND v_role = 'teacher')
      OR v_role = 'admin'
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.announcement_reads ar
      WHERE ar.announcement_id = a.id AND ar.user_id = v_user_id
    );
  
  RETURN v_count;
END;
$$;

CREATE FUNCTION public.get_user_role(user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT role::TEXT FROM public.profiles WHERE id = user_id;
$$;

COMMENT ON FUNCTION public.get_user_role(user_id uuid) IS 'Get user role without causing recursion - uses SECURITY DEFINER';

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only create profile if it doesn't exist (prevents duplicate key errors)
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.id) THEN
    INSERT INTO public.profiles (id, email, full_name, role)
    VALUES (
      NEW.id,
      NEW.email,
      COALESCE(
        NEW.raw_user_meta_data->>'full_name',
        NEW.raw_user_meta_data->>'name',
        ''
      ),
      COALESCE(
        (NEW.raw_user_meta_data->>'role')::user_role,
        'student'::user_role
      )
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.is_admin(user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = user_id AND role = 'admin'
  );
END;
$$;

COMMENT ON FUNCTION public.is_admin(user_id uuid) IS 'Check if user has admin role without causing recursion';

CREATE FUNCTION public.is_course_facilitator(p_course_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.course_staff s WHERE s.course_id = p_course_id AND s.user_id = p_user_id
  );
$$;

CREATE FUNCTION public.is_course_wide_facilitator(p_course_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.course_staff s WHERE s.course_id = p_course_id AND s.user_id = p_user_id AND s.cohort_id IS NULL
  );
$$;

CREATE FUNCTION public.is_privileged_context() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') = 'service_role' THEN
    RETURN true;
  END IF;
  IF session_user NOT IN ('authenticator', 'supabase_auth_admin') THEN
    RETURN true;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$;

CREATE FUNCTION public.is_submission_instructor(p_type text, p_submission_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_admin(auth.uid()) OR EXISTS (
    SELECT 1 FROM public.submission_owner(p_type, p_submission_id) o
    JOIN public.courses c ON c.id = o.course_id WHERE c.teacher_id = auth.uid()
  );
$$;

CREATE FUNCTION public.is_valid_rubric(p_rubric jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_criterion jsonb;
  v_level jsonb;
BEGIN
  IF p_rubric IS NULL THEN RETURN true; END IF;
  IF jsonb_typeof(p_rubric) <> 'object' OR jsonb_typeof(p_rubric -> 'criteria') <> 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(p_rubric -> 'criteria') NOT BETWEEN 1 AND 20 THEN RETURN false; END IF;
  FOR v_criterion IN SELECT * FROM jsonb_array_elements(p_rubric -> 'criteria') LOOP
    IF jsonb_typeof(v_criterion -> 'id') <> 'string' OR jsonb_typeof(v_criterion -> 'title') <> 'string'
       OR length(btrim(v_criterion ->> 'title')) = 0 OR jsonb_typeof(v_criterion -> 'levels') <> 'array'
       OR jsonb_array_length(v_criterion -> 'levels') NOT BETWEEN 1 AND 8 THEN
      RETURN false;
    END IF;
    FOR v_level IN SELECT * FROM jsonb_array_elements(v_criterion -> 'levels') LOOP
      IF jsonb_typeof(v_level -> 'label') <> 'string' OR jsonb_typeof(v_level -> 'points') <> 'number'
         OR (v_level ->> 'points')::numeric < 0 THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;
  RETURN true;
END;
$$;

CREATE FUNCTION public.issue_certificate_if_eligible(p_student_id uuid, p_course_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule public.course_certificate_rules%ROWTYPE;
  v_min integer := 65;
  v_require_lessons boolean := false;
  v_auto boolean := true;
  v_grade integer;
  v_total integer;
  v_done integer;
  v_existing public.certificates%ROWTYPE;
  v_id uuid;
BEGIN
  SELECT * INTO v_rule FROM public.course_certificate_rules WHERE course_id = p_course_id;
  IF FOUND THEN
    v_min := v_rule.min_capstone_grade;
    v_require_lessons := v_rule.require_all_lessons;
    v_auto := v_rule.auto_issue;
  END IF;
  IF NOT v_auto THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.course_enrollments WHERE student_id = p_student_id AND course_id = p_course_id
  ) THEN
    RETURN NULL;
  END IF;

  SELECT max(cs.grade) INTO v_grade
  FROM public.capstone_submissions cs
  JOIN public.capstone_projects cp ON cp.id = cs.capstone_project_id
  WHERE cp.course_id = p_course_id AND cs.student_id = p_student_id;
  IF v_grade IS NULL OR v_grade < v_min THEN
    RETURN NULL;
  END IF;

  IF v_require_lessons THEN
    SELECT count(l.id), count(l.id) FILTER (WHERE p.is_completed)
      INTO v_total, v_done
    FROM public.course_chapters ch
    JOIN public.course_lessons l ON l.chapter_id = ch.id
    LEFT JOIN public.student_lesson_progress p ON p.lesson_id = l.id AND p.student_id = p_student_id
    WHERE ch.course_id = p_course_id;
    IF v_total = 0 OR v_done < v_total THEN
      RETURN NULL;
    END IF;
  END IF;

  SELECT * INTO v_existing FROM public.certificates
  WHERE student_id = p_student_id AND course_id = p_course_id;

  IF FOUND THEN
    IF v_existing.status IN ('approved', 'revoked', 'rejected') THEN
      RETURN v_existing.id;
    END IF;
    UPDATE public.certificates
    SET status = 'approved', approved_at = now(), issued_at = now(),
        issue_source = 'auto', capstone_grade = v_grade, grade = v_grade::text, updated_at = now()
    WHERE id = v_existing.id
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO public.certificates
      (student_id, course_id, status, approved_at, issued_at, completion_date,
       issue_source, capstone_grade, grade)
    VALUES (p_student_id, p_course_id, 'approved', now(), now(), now(), 'auto', v_grade, v_grade::text)
    RETURNING id INTO v_id;
  END IF;

  UPDATE public.course_enrollments
  SET completed = true,
      completion_date = coalesce(completion_date, now()),
      final_grade = coalesce(final_grade, v_grade::text)
  WHERE student_id = p_student_id AND course_id = p_course_id;

  RETURN v_id;
END;
$$;

CREATE FUNCTION public.issue_pending_certificates() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_before integer;
  v_after integer;
BEGIN
  IF NOT public.is_privileged_context() THEN
    RAISE EXCEPTION 'Only admins can issue pending certificates' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO v_before FROM public.certificates WHERE status = 'approved';
  FOR r IN
    SELECT DISTINCT cs.student_id, cp.course_id
    FROM public.capstone_submissions cs
    JOIN public.capstone_projects cp ON cp.id = cs.capstone_project_id
    WHERE cs.grade IS NOT NULL
  LOOP
    PERFORM public.issue_certificate_if_eligible(r.student_id, r.course_id);
  END LOOP;
  SELECT count(*) INTO v_after FROM public.certificates WHERE status = 'approved';
  RETURN v_after - v_before;
END;
$$;

CREATE FUNCTION public.lesson_file_ref_matches(p_stored text, p_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT p_stored IS NOT NULL AND p_name IS NOT NULL AND (
    ltrim(p_stored, '/') = p_name
    OR ltrim(p_stored, '/') = 'lesson-files/' || p_name
    OR right(split_part(p_stored, '?', 1), length(p_name) + 14) = '/lesson-files/' || p_name
  );
$$;

CREATE FUNCTION public.log_activity(p_user_id uuid, p_action text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_log_id UUID;
BEGIN
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id, details)
  VALUES (p_user_id, p_action, p_entity_type, p_entity_id, p_details)
  RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$$;

CREATE FUNCTION public.log_suspension_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF OLD.is_suspended IS DISTINCT FROM NEW.is_suspended THEN
    INSERT INTO public.activity_logs (
      user_id,
      action,
      entity_type,
      entity_id,
      details
    ) VALUES (
      auth.uid(),
      CASE 
        WHEN NEW.is_suspended THEN 'user_suspended'
        ELSE 'user_unsuspended'
      END,
      'profile',
      NEW.id,
      jsonb_build_object(
        'reason', NEW.suspension_reason,
        'changed_at', NOW()
      )
    );
  END IF;
  
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.log_suspension_change() IS 'Logs when a user is suspended or unsuspended';

CREATE FUNCTION public.mark_conversation_read(p_conversation_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.conversations
    WHERE id = p_conversation_id AND (student_id = auth.uid() OR teacher_id = auth.uid())
  ) THEN
    RAISE EXCEPTION 'Conversation not found' USING ERRCODE = '42501';
  END IF;
  UPDATE public.direct_messages
  SET is_read = true
  WHERE conversation_id = p_conversation_id
    AND sender_id <> auth.uid()
    AND coalesce(is_read, false) = false;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

CREATE FUNCTION public.mark_course_completed(p_student_id uuid, p_course_id uuid, p_final_grade text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.course_enrollments
  SET completed = TRUE, completion_date = NOW(), final_grade = p_final_grade, progress_percentage = 100
  WHERE student_id = p_student_id AND course_id = p_course_id;
  
  INSERT INTO public.certificates (student_id, course_id, status, completion_date, grade)
  VALUES (p_student_id, p_course_id, 'pending', NOW(), p_final_grade)
  ON CONFLICT (student_id, course_id) DO NOTHING;
  
  RETURN TRUE;
END;
$$;

CREATE FUNCTION public.mark_notifications_read(p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.notifications
  SET read_at = now()
  WHERE user_id = auth.uid() AND read_at IS NULL
    AND (p_ids IS NULL OR id = ANY (p_ids));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

CREATE FUNCTION public.new_verification_code() RETURNS text
    LANGUAGE sql
    AS $$
  SELECT upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
$$;

CREATE FUNCTION public.next_certificate_number() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'DPA-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.certificate_number_seq')::text, 6, '0');
$$;

CREATE FUNCTION public.notify_on_application() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_label text;
  v_kind text;
BEGIN
  IF TG_TABLE_NAME = 'scholarship_applications' THEN
    SELECT c.title INTO v_label FROM public.courses c WHERE c.id = NEW.course_id;
    v_kind := 'scholarship';
  ELSE
    SELECT co.name INTO v_label FROM public.cohorts co WHERE co.id = NEW.cohort_id;
    v_kind := 'cohort';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM public.notify_user(
      NEW.student_id, 'application_received',
      CASE v_kind WHEN 'scholarship' THEN 'Scholarship application received'
                  ELSE 'Cohort request received' END,
      'We received your application for ' || coalesce(v_label, 'the programme') || '. You will be notified when it is reviewed.',
      '/student/dashboard',
      jsonb_build_object('kind', v_kind, 'application_id', NEW.id), true);
  ELSIF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved', 'rejected') THEN
    PERFORM public.notify_user(
      NEW.student_id, 'application_decision',
      CASE WHEN NEW.status = 'approved' THEN 'Application approved' ELSE 'Application not approved' END,
      'Your ' || v_kind || ' application for ' || coalesce(v_label, 'the programme') || ' was ' ||
        CASE WHEN NEW.status = 'approved' THEN 'approved.' ELSE 'not approved this time.' END,
      '/student/dashboard',
      jsonb_build_object('kind', v_kind, 'application_id', NEW.id, 'status', NEW.status), true);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.notify_on_certificate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_title text;
BEGIN
  SELECT title INTO v_title FROM public.courses WHERE id = NEW.course_id;
  IF NEW.status = 'approved' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    PERFORM public.notify_user(
      NEW.student_id, 'certificate_issued', 'Your certificate is ready',
      'You earned the certificate for ' || coalesce(v_title, 'your course') || '.',
      '/student/certificates',
      jsonb_build_object('course_id', NEW.course_id, 'certificate_id', NEW.id), false);
  ELSIF TG_OP = 'UPDATE' AND NEW.status = 'revoked' AND OLD.status IS DISTINCT FROM 'revoked' THEN
    PERFORM public.notify_user(
      NEW.student_id, 'certificate_revoked', 'A certificate was revoked',
      'The certificate for ' || coalesce(v_title, 'your course') || ' is no longer valid.',
      '/student/certificates',
      jsonb_build_object('course_id', NEW.course_id, 'certificate_id', NEW.id), false);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.notify_on_session_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_title text;
  v_type text;
  s record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_type := 'session_scheduled'; v_title := 'New session: ' || NEW.title;
  ELSIF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    v_type := 'session_cancelled'; v_title := 'Session cancelled: ' || NEW.title;
  ELSIF NEW.scheduled_time IS DISTINCT FROM OLD.scheduled_time
     OR NEW.location IS DISTINCT FROM OLD.location
     OR NEW.modality IS DISTINCT FROM OLD.modality THEN
    v_type := 'session_changed'; v_title := 'Session updated: ' || NEW.title;
  ELSE
    RETURN NEW;
  END IF;

  FOR s IN
    SELECT e.student_id FROM public.course_enrollments e
    WHERE e.course_id = NEW.course_id
      AND (NEW.cohort_id IS NULL OR e.cohort_id IS NULL OR e.cohort_id = NEW.cohort_id)
  LOOP
    PERFORM public.notify_user(
      s.student_id, v_type, v_title,
      to_char(NEW.scheduled_time AT TIME ZONE 'Africa/Kigali', 'Dy DD Mon, HH24:MI') || ' (Kigali time)',
      '/student/schedule',
      jsonb_build_object('course_id', NEW.course_id, 'session_id', NEW.id), false);
  END LOOP;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.notify_on_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_course uuid;
  v_course_title text;
  v_teacher uuid;
  v_item text;
  v_kind text;
BEGIN
  IF TG_TABLE_NAME = 'capstone_submissions' THEN
    SELECT c.id, c.title, c.teacher_id, cp.title INTO v_course, v_course_title, v_teacher, v_item
    FROM public.capstone_projects cp JOIN public.courses c ON c.id = cp.course_id
    WHERE cp.id = NEW.capstone_project_id;
    v_kind := 'capstone';
  ELSE
    SELECT c.id, c.title, c.teacher_id, l.title INTO v_course, v_course_title, v_teacher, v_item
    FROM public.course_lessons l
    JOIN public.course_chapters ch ON ch.id = l.chapter_id
    JOIN public.courses c ON c.id = ch.course_id
    WHERE l.id = NEW.lesson_id;
    v_kind := 'assignment';
  END IF;

  IF TG_OP = 'INSERT'
     OR (TG_OP = 'UPDATE' AND NEW.submitted_at IS DISTINCT FROM OLD.submitted_at) THEN
    PERFORM public.notify_user(
      NEW.student_id, 'submission_received',
      'Submission received: ' || coalesce(v_item, 'your work'),
      'Your ' || v_kind || ' for ' || coalesce(v_course_title, 'your course') || ' was submitted.',
      '/student/assignments',
      jsonb_build_object('course_id', v_course, 'kind', v_kind, 'submission_id', NEW.id), true);
    PERFORM public.notify_user(
      v_teacher, 'new_submission',
      'New ' || v_kind || ' submission',
      coalesce(v_item, 'A submission') || ' in ' || coalesce(v_course_title, 'your course') || ' is ready to review.',
      '/teacher/assignments',
      jsonb_build_object('course_id', v_course, 'kind', v_kind, 'submission_id', NEW.id), false);
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.grade IS NOT NULL AND NEW.grade IS DISTINCT FROM OLD.grade THEN
    PERFORM public.notify_user(
      NEW.student_id, 'submission_graded',
      'Graded: ' || coalesce(v_item, 'your work'),
      'You received ' || NEW.grade || '/100 for your ' || v_kind || ' in ' || coalesce(v_course_title, 'your course') || '.',
      '/student/scores',
      jsonb_build_object('course_id', v_course, 'kind', v_kind, 'submission_id', NEW.id, 'grade', NEW.grade), true);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.notify_on_teacher_announcement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s record;
BEGIN
  IF NOT coalesce(NEW.is_active, true) THEN
    RETURN NEW;
  END IF;
  FOR s IN
    SELECT DISTINCT e.student_id
    FROM public.course_enrollments e JOIN public.courses c ON c.id = e.course_id
    WHERE (NEW.course_id IS NOT NULL AND e.course_id = NEW.course_id)
       OR (NEW.course_id IS NULL AND c.teacher_id = NEW.teacher_id)
  LOOP
    PERFORM public.notify_user(
      s.student_id, 'announcement', NEW.title, left(NEW.message, 240),
      '/student/dashboard',
      jsonb_build_object('course_id', NEW.course_id, 'announcement_id', NEW.id), false);
  END LOOP;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.notify_user(p_user_id uuid, p_type text, p_title text, p_body text DEFAULT NULL::text, p_link text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb, p_email boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;
  -- A muted type is skipped in-app. Email for applications and
  -- submissions is transactional and is still queued.
  IF NOT p_email AND EXISTS (
    SELECT 1 FROM public.notification_preferences np
    WHERE np.user_id = p_user_id AND p_type = ANY (np.muted_types)
  ) THEN
    RETURN;
  END IF;
  INSERT INTO public.notifications (user_id, type, title, body, link, data, email_status)
  VALUES (p_user_id, p_type, p_title, p_body, p_link, coalesce(p_data, '{}'::jsonb),
          CASE WHEN p_email THEN 'pending' END);
END;
$$;

CREATE FUNCTION public.on_capstone_graded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_course uuid;
BEGIN
  IF NEW.grade IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.grade IS NOT DISTINCT FROM OLD.grade THEN
    RETURN NEW;
  END IF;
  SELECT course_id INTO v_course FROM public.capstone_projects WHERE id = NEW.capstone_project_id;
  IF v_course IS NOT NULL THEN
    PERFORM public.issue_certificate_if_eligible(NEW.student_id, v_course);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.on_lesson_completed_check_certificate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_course uuid;
BEGIN
  IF NOT coalesce(NEW.is_completed, false) THEN
    RETURN NEW;
  END IF;
  SELECT ch.course_id INTO v_course
  FROM public.course_lessons l JOIN public.course_chapters ch ON ch.id = l.chapter_id
  WHERE l.id = NEW.lesson_id;
  IF v_course IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.course_certificate_rules r
    WHERE r.course_id = v_course AND r.require_all_lessons AND r.auto_issue
  ) THEN
    PERFORM public.issue_certificate_if_eligible(NEW.student_id, v_course);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.on_lesson_progress_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_course uuid;
BEGIN
  SELECT ch.course_id INTO v_course
  FROM public.course_lessons l JOIN public.course_chapters ch ON ch.id = l.chapter_id
  WHERE l.id = NEW.lesson_id;
  IF v_course IS NOT NULL THEN
    PERFORM public.refresh_enrollment_progress(NEW.student_id, v_course);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.protect_competition_judging() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_privileged_context() THEN
    RETURN NEW;
  END IF;
  NEW.status := 'submitted';
  NEW.score := NULL;
  NEW.judge_feedback := NULL;
  NEW.scored_by := NULL;
  NEW.scored_at := NULL;
  NEW.submitted_at := now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.protect_profile_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_privileged_context() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- A new account can be a student or a teacher, never an admin, and
    -- never pre-approved, suspended or on a special pricing tier.
    IF NEW.role IS NULL OR NEW.role::text NOT IN ('student', 'teacher') THEN
      NEW.role := 'student';
    END IF;
    NEW.teacher_approved := false;
    NEW.teacher_approved_by := NULL;
    NEW.teacher_approval_date := NULL;
    NEW.is_suspended := false;
    NEW.suspension_reason := NULL;
    NEW.pricing_tier := 'standard';
    RETURN NEW;
  END IF;

  -- UPDATE by the account owner.
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    -- Choosing student or teacher is allowed only until onboarding is done.
    IF coalesce(OLD.onboarding_completed, false)
       OR OLD.role::text = 'admin'
       OR NEW.role::text NOT IN ('student', 'teacher') THEN
      NEW.role := OLD.role;
    END IF;
  END IF;

  NEW.teacher_approved := OLD.teacher_approved;
  NEW.teacher_approved_by := OLD.teacher_approved_by;
  NEW.teacher_approval_date := OLD.teacher_approval_date;
  NEW.teacher_rejection_reason := OLD.teacher_rejection_reason;
  NEW.is_suspended := OLD.is_suspended;
  NEW.suspension_reason := OLD.suspension_reason;
  NEW.pricing_tier := OLD.pricing_tier;
  -- A teacher may move their own request back to "pending", nothing else.
  IF NEW.teacher_approval_status IS DISTINCT FROM OLD.teacher_approval_status
     AND coalesce(NEW.teacher_approval_status, 'pending') <> 'pending' THEN
    NEW.teacher_approval_status := OLD.teacher_approval_status;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.protect_submission_grade() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_staff boolean;
BEGIN
  IF public.is_privileged_context() THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'capstone_submissions' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.capstone_projects cp
      JOIN public.courses c ON c.id = cp.course_id
      WHERE cp.id = NEW.capstone_project_id AND c.teacher_id = auth.uid()
    ) INTO v_is_staff;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.course_lessons l
      JOIN public.course_chapters ch ON ch.id = l.chapter_id
      JOIN public.courses c ON c.id = ch.course_id
      WHERE l.id = NEW.lesson_id AND c.teacher_id = auth.uid()
    ) INTO v_is_staff;
  END IF;

  IF v_is_staff THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.grade := NULL;
    NEW.feedback := NULL;
    NEW.graded_at := NULL;
  ELSE
    NEW.grade := OLD.grade;
    NEW.feedback := OLD.feedback;
    NEW.graded_at := OLD.graded_at;
  END IF;
  IF TG_TABLE_NAME = 'capstone_submissions' THEN
    IF TG_OP = 'INSERT' THEN
      NEW.graded_by := NULL;
    ELSE
      NEW.graded_by := OLD.graded_by;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.protect_submission_rubric_scores() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_staff boolean;
BEGIN
  IF public.is_privileged_context() THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'capstone_submissions' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.capstone_projects cp JOIN public.courses c ON c.id = cp.course_id
      WHERE cp.id = NEW.capstone_project_id AND c.teacher_id = auth.uid()
    ) INTO v_is_staff;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.course_lessons l
      JOIN public.course_chapters ch ON ch.id = l.chapter_id
      JOIN public.courses c ON c.id = ch.course_id
      WHERE l.id = NEW.lesson_id AND c.teacher_id = auth.uid()
    ) INTO v_is_staff;
  END IF;
  IF NOT v_is_staff THEN
    NEW.rubric_scores := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.rubric_scores END;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.record_grade_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.grade IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.grade IS NOT DISTINCT FROM OLD.grade
     AND NEW.feedback IS NOT DISTINCT FROM OLD.feedback
     AND NEW.rubric_scores IS NOT DISTINCT FROM OLD.rubric_scores THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.grade_history (submission_type, submission_id, student_id, grade, feedback, rubric_scores, graded_by)
  VALUES (
    CASE WHEN TG_TABLE_NAME = 'capstone_submissions' THEN 'capstone' ELSE 'assignment' END,
    NEW.id, NEW.student_id, NEW.grade, NEW.feedback, NEW.rubric_scores, auth.uid()
  );
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.record_lesson_visit(p_lesson_id uuid, p_position integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_course uuid;
BEGIN
  IF v_user IS NULL THEN
    RETURN;
  END IF;
  SELECT ch.course_id INTO v_course
  FROM public.course_lessons l JOIN public.course_chapters ch ON ch.id = l.chapter_id
  WHERE l.id = p_lesson_id;
  IF v_course IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.course_enrollments WHERE student_id = v_user AND course_id = v_course
  ) THEN
    RETURN;
  END IF;

  INSERT INTO public.student_lesson_progress (student_id, lesson_id, is_completed, last_position)
  VALUES (v_user, p_lesson_id, false, coalesce(p_position, 0))
  ON CONFLICT (student_id, lesson_id)
  DO UPDATE SET last_position = coalesce(p_position, public.student_lesson_progress.last_position);

  UPDATE public.course_enrollments
  SET last_lesson_id = p_lesson_id, last_activity_at = now()
  WHERE student_id = v_user AND course_id = v_course;
END;
$$;

CREATE FUNCTION public.redeem_coupon_for_payment(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment RECORD;
  v_updated INT;
  v_coupon_type TEXT;
BEGIN
  SELECT * INTO v_payment FROM public.payments WHERE id = p_payment_id;

  IF NOT FOUND OR v_payment.coupon_id IS NULL OR v_payment.status <> 'success' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Nothing to redeem');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coupon_redemptions WHERE payment_id = p_payment_id) THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already redeemed');
  END IF;

  UPDATE public.coupons
  SET uses_count = uses_count + 1, updated_at = now()
  WHERE id = v_payment.coupon_id
    AND (max_uses IS NULL OR uses_count < max_uses);

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Coupon usage limit reached');
  END IF;

  INSERT INTO public.coupon_redemptions (coupon_id, student_id, payment_id, discount_amount)
  VALUES (v_payment.coupon_id, v_payment.student_id, p_payment_id, COALESCE(v_payment.discount_amount, 0));

  SELECT coupon_type INTO v_coupon_type FROM public.coupons WHERE id = v_payment.coupon_id;

  IF v_coupon_type = 'scholarship' THEN
    UPDATE public.scholarship_applications
    SET status = 'redeemed', updated_at = now()
    WHERE coupon_id = v_payment.coupon_id AND student_id = v_payment.student_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE FUNCTION public.refresh_enrollment_progress(p_student_id uuid, p_course_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total integer;
  v_done integer;
BEGIN
  SELECT count(l.id),
         count(l.id) FILTER (WHERE p.is_completed)
    INTO v_total, v_done
  FROM public.course_chapters ch
  JOIN public.course_lessons l ON l.chapter_id = ch.id
  LEFT JOIN public.student_lesson_progress p
    ON p.lesson_id = l.id AND p.student_id = p_student_id
  WHERE ch.course_id = p_course_id;

  UPDATE public.course_enrollments
  SET progress_percentage = CASE WHEN v_total > 0 THEN round(v_done * 100.0 / v_total)::integer ELSE 0 END
  WHERE student_id = p_student_id AND course_id = p_course_id;
END;
$$;

CREATE FUNCTION public.reinstate_certificate(p_certificate_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Only admins can reinstate certificates' USING ERRCODE = '42501';
  END IF;
  UPDATE public.certificates
  SET status = 'approved', revoked_at = NULL, revoked_by = NULL, revoked_reason = NULL, updated_at = now()
  WHERE id = p_certificate_id AND status = 'revoked';
END;
$$;

CREATE FUNCTION public.reject_course_update(p_course_id uuid, p_review_notes text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can reject course updates';
  END IF;

  -- Reject the update
  UPDATE public.courses
  SET 
    pending_update = false,
    update_notes = NULL
  WHERE id = p_course_id;

  -- Update history
  UPDATE public.course_update_history
  SET 
    status = 'rejected',
    reviewed_by = auth.uid(),
    review_notes = p_review_notes,
    reviewed_at = NOW()
  WHERE course_id = p_course_id AND status = 'pending';

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'course_update_rejected', 'course', p_course_id, jsonb_build_object('reason', p_review_notes));

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.reject_course_update(p_course_id uuid, p_review_notes text) IS 'Admins reject pending course updates';

CREATE FUNCTION public.reject_scholarship_application(p_application_id uuid, p_admin_id uuid, p_admin_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id UUID;
BEGIN
  v_admin_id := auth.uid();
  IF v_admin_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  UPDATE public.scholarship_applications
  SET
    status = 'rejected',
    reviewed_by = v_admin_id,
    reviewed_at = now(),
    admin_notes = p_admin_notes,
    updated_at = now()
  WHERE id = p_application_id AND status = 'pending';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found or already reviewed');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE FUNCTION public.reject_teacher(p_teacher_id uuid, p_rejection_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can reject teachers';
  END IF;

  -- Reject the teacher
  UPDATE public.profiles
  SET 
    teacher_approved = false,
    teacher_approval_status = 'rejected',
    teacher_approval_date = NOW(),
    teacher_approved_by = auth.uid(),
    teacher_rejection_reason = p_rejection_reason
  WHERE id = p_teacher_id AND role = 'teacher';

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'teacher_rejected', 'profile', p_teacher_id, jsonb_build_object('reason', p_rejection_reason));

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.reject_teacher(p_teacher_id uuid, p_rejection_reason text) IS 'Reject a teacher account with reason (admin only)';

CREATE FUNCTION public.require_grade_feedback() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.grade IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.grade IS DISTINCT FROM OLD.grade OR NEW.feedback IS DISTINCT FROM OLD.feedback)
     AND length(btrim(coalesce(NEW.feedback, ''))) < 20 THEN
    RAISE EXCEPTION 'A mark must be published with written feedback of at least 20 characters'
      USING ERRCODE = '23514', HINT = 'feedback_required';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.revoke_certificate(p_certificate_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Only admins can revoke certificates' USING ERRCODE = '42501';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to revoke a certificate';
  END IF;
  UPDATE public.certificates
  SET status = 'revoked', revoked_at = now(), revoked_by = auth.uid(),
      revoked_reason = p_reason, updated_at = now()
  WHERE id = p_certificate_id;
END;
$$;

CREATE FUNCTION public.set_cohort_discord_url(p_cohort_id uuid, p_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cohort public.cohorts%ROWTYPE;
BEGIN
  SELECT * INTO v_cohort FROM public.cohorts WHERE id = p_cohort_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cohort not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    v_cohort.teacher_id = auth.uid()
    OR public.is_admin(auth.uid())
    OR EXISTS (SELECT 1 FROM public.course_staff s WHERE s.user_id = auth.uid() AND s.course_id = v_cohort.course_id
               AND (s.cohort_id IS NULL OR s.cohort_id = p_cohort_id))
  ) THEN
    RAISE EXCEPTION 'You cannot change this cohort' USING ERRCODE = '42501';
  END IF;
  UPDATE public.cohorts SET discord_url = nullif(btrim(p_url), ''), updated_at = now() WHERE id = p_cohort_id;
END;
$$;

CREATE FUNCTION public.stamp_learner_preferences() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  IF NEW.research_consent AND (TG_OP = 'INSERT' OR NOT OLD.research_consent) THEN
    NEW.research_consent_at := now();
  ELSIF NOT NEW.research_consent THEN
    NEW.research_consent_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.stamp_submission_review() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.submission_owner(p_type text, p_submission_id uuid) RETURNS TABLE(course_id uuid, student_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.course_of_lesson(s.lesson_id), s.student_id FROM public.assignment_submissions s
  WHERE p_type = 'assignment' AND s.id = p_submission_id
  UNION ALL
  SELECT public.course_of_capstone(s.capstone_project_id), s.student_id FROM public.capstone_submissions s
  WHERE p_type = 'capstone' AND s.id = p_submission_id;
$$;

CREATE FUNCTION public.submit_course_update(p_course_id uuid, p_update_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is the course owner
  IF NOT EXISTS (
    SELECT 1 FROM public.courses 
    WHERE id = p_course_id AND teacher_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'You can only update your own courses';
  END IF;

  -- Mark course as having pending update
  UPDATE public.courses
  SET 
    pending_update = true,
    update_submitted_at = NOW(),
    update_notes = p_update_notes
  WHERE id = p_course_id;

  -- Log the update
  INSERT INTO public.course_update_history (
    course_id,
    updated_by,
    update_type,
    status
  ) VALUES (
    p_course_id,
    auth.uid(),
    'updated',
    'pending'
  );

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.submit_course_update(p_course_id uuid, p_update_notes text) IS 'Teachers submit course updates for admin review';

CREATE FUNCTION public.submit_lesson_quiz(p_lesson_id uuid, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_score integer := 0;
  v_total integer := 0;
  v_passed boolean;
  v_review jsonb := '[]'::jsonb;
  v_attempt uuid;
  q record;
BEGIN
  IF v_user IS NULL OR NOT public.can_access_lesson(p_lesson_id) THEN
    RAISE EXCEPTION 'You do not have access to this quiz' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_user AND role = 'student') THEN
    RAISE EXCEPTION 'Only students can submit a quiz' USING ERRCODE = '42501';
  END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'object' THEN
    RAISE EXCEPTION 'Answers must be an object of question id to option id';
  END IF;

  FOR q IN
    SELECT lq.id, lq.correct_answer, lq.explanation, coalesce(lq.points, 1) AS points
    FROM public.lesson_quiz_questions lq
    WHERE lq.lesson_id = p_lesson_id
    ORDER BY lq.order_index, lq.created_at
  LOOP
    v_total := v_total + q.points;
    IF p_answers->>(q.id::text) = q.correct_answer THEN
      v_score := v_score + q.points;
    END IF;
    v_review := v_review || jsonb_build_object(
      'question_id', q.id,
      'selected', p_answers->>(q.id::text),
      'correct_answer', q.correct_answer,
      'is_correct', (p_answers->>(q.id::text) = q.correct_answer),
      'explanation', q.explanation
    );
  END LOOP;

  IF v_total = 0 THEN
    RAISE EXCEPTION 'This quiz has no questions yet';
  END IF;

  v_passed := v_score >= ceil(v_total * 0.6);

  INSERT INTO public.student_quiz_attempts
    (student_id, lesson_id, answers, score, total_points, passed)
  VALUES (v_user, p_lesson_id, p_answers, v_score, v_total, v_passed)
  RETURNING id INTO v_attempt;

  IF v_passed THEN
    INSERT INTO public.student_lesson_progress (student_id, lesson_id, is_completed, completed_at)
    VALUES (v_user, p_lesson_id, true, now())
    ON CONFLICT (student_id, lesson_id)
    DO UPDATE SET is_completed = true,
                  completed_at = coalesce(public.student_lesson_progress.completed_at, now());
  END IF;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt, 'score', v_score, 'total_points', v_total,
    'passed', v_passed, 'review', v_review
  );
END;
$$;

CREATE FUNCTION public.suspend_user(p_user_id uuid, p_suspension_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can suspend users';
  END IF;

  -- Prevent suspending admins
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Cannot suspend admin accounts';
  END IF;

  -- Suspend the user
  UPDATE public.profiles
  SET 
    is_suspended = true,
    suspension_reason = p_suspension_reason,
    updated_at = NOW()
  WHERE id = p_user_id;

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'user_suspended', 'profile', p_user_id, jsonb_build_object('reason', p_suspension_reason));

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.suspend_user(p_user_id uuid, p_suspension_reason text) IS 'Suspend a user account with reason (admin only)';

CREATE FUNCTION public.unsuspend_user(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can unsuspend users';
  END IF;

  -- Unsuspend the user
  UPDATE public.profiles
  SET 
    is_suspended = false,
    suspension_reason = NULL,
    updated_at = NOW()
  WHERE id = p_user_id;

  -- Log activity
  INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id)
  VALUES (auth.uid(), 'user_unsuspended', 'profile', p_user_id);

  RETURN true;
END;
$$;

COMMENT ON FUNCTION public.unsuspend_user(p_user_id uuid) IS 'Unsuspend a user account (admin only)';

