CREATE FUNCTION public.update_user_pricing_tier(p_user_id uuid, p_pricing_tier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  IF p_pricing_tier NOT IN ('standard', 'student', 'ngo', 'corporate', 'partner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid pricing tier');
  END IF;

  UPDATE public.profiles
  SET pricing_tier = p_pricing_tier, updated_at = now()
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  RETURN jsonb_build_object('success', true, 'pricing_tier', p_pricing_tier);
END;
$$;

CREATE FUNCTION public.validate_coupon(p_code text, p_student_id uuid, p_course_id uuid DEFAULT NULL::uuid, p_bundle_id uuid DEFAULT NULL::uuid, p_original_amount numeric DEFAULT 0, p_currency text DEFAULT 'RWF'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_coupon RECORD;
  v_discount NUMERIC;
  v_final NUMERIC;
  v_user_uses INT;
  v_code TEXT;
BEGIN
  v_code := UPPER(TRIM(p_code));
  IF v_code = '' OR v_code IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Coupon code is required');
  END IF;

  SELECT * INTO v_coupon
  FROM public.coupons
  WHERE UPPER(code) = v_code;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Invalid coupon code');
  END IF;

  IF NOT v_coupon.is_active THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon is no longer active');
  END IF;

  IF v_coupon.valid_from IS NOT NULL AND v_coupon.valid_from > now() THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon is not yet valid');
  END IF;

  IF v_coupon.valid_until IS NOT NULL AND v_coupon.valid_until < now() THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon has expired');
  END IF;

  IF v_coupon.max_uses IS NOT NULL AND v_coupon.uses_count >= v_coupon.max_uses THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon has already been used');
  END IF;

  IF v_coupon.applies_to = 'course' AND (p_course_id IS NULL OR v_coupon.course_id <> p_course_id) THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon does not apply to this course');
  END IF;

  IF v_coupon.applies_to = 'bundle' AND (p_bundle_id IS NULL OR v_coupon.bundle_id <> p_bundle_id) THEN
    RETURN jsonb_build_object('valid', false, 'error', 'This coupon does not apply to this bundle');
  END IF;

  IF COALESCE(v_coupon.coupon_type, 'promo') = 'scholarship' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.scholarship_applications sa
      WHERE sa.coupon_id = v_coupon.id
        AND sa.student_id = p_student_id
        AND sa.status = 'approved'
    ) THEN
      RETURN jsonb_build_object('valid', false, 'error', 'This scholarship code is not assigned to your account');
    END IF;
  END IF;

  IF v_coupon.min_purchase_amount IS NOT NULL AND p_original_amount < v_coupon.min_purchase_amount THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Minimum purchase amount not met');
  END IF;

  IF v_coupon.max_uses_per_user IS NOT NULL THEN
    SELECT COUNT(*) INTO v_user_uses
    FROM public.coupon_redemptions cr
    JOIN public.payments p ON p.id = cr.payment_id
    WHERE cr.coupon_id = v_coupon.id
      AND cr.student_id = p_student_id
      AND p.status = 'success';

    IF v_user_uses >= v_coupon.max_uses_per_user THEN
      RETURN jsonb_build_object('valid', false, 'error', 'You have already used this coupon');
    END IF;
  END IF;

  IF v_coupon.discount_type = 'percent' THEN
    v_discount := ROUND(p_original_amount * (v_coupon.discount_value / 100.0), 2);
  ELSE
    IF v_coupon.currency IS NOT NULL AND UPPER(v_coupon.currency) <> UPPER(COALESCE(p_currency, 'RWF')) THEN
      RETURN jsonb_build_object('valid', false, 'error', 'Coupon currency does not match purchase currency');
    END IF;
    v_discount := LEAST(v_coupon.discount_value, p_original_amount);
  END IF;

  v_final := GREATEST(p_original_amount - v_discount, 0);

  RETURN jsonb_build_object(
    'valid', true,
    'coupon_id', v_coupon.id,
    'code', v_coupon.code,
    'discount_type', v_coupon.discount_type,
    'discount_value', v_coupon.discount_value,
    'original_amount', p_original_amount,
    'discount_amount', v_discount,
    'final_amount', v_final,
    'currency', p_currency
  );
END;
$$;

CREATE FUNCTION public.validate_course_staff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.cohort_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.cohorts WHERE id = NEW.cohort_id AND course_id = NEW.course_id
  ) THEN
    RAISE EXCEPTION 'This cohort does not belong to the course' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.courses WHERE id = NEW.course_id AND teacher_id = NEW.user_id) THEN
    RAISE EXCEPTION 'The course instructor cannot also be its facilitator' USING ERRCODE = '23514';
  END IF;
  IF public.is_admin(NEW.user_id) THEN
    RAISE EXCEPTION 'Administrators already have full access' USING ERRCODE = '23514';
  END IF;
  IF auth.uid() IS NOT NULL THEN
    NEW.assigned_by := auth.uid();
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.verify_certificate(p_code text) RETURNS TABLE(certificate_number text, holder_name text, course_title text, issued_at timestamp with time zone, completion_date timestamp with time zone, is_valid boolean, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.certificate_number,
         p.full_name::text,
         co.title::text,
         c.issued_at,
         c.completion_date,
         (c.status = 'approved'),
         c.status::text
  FROM public.certificates c
  JOIN public.profiles p ON p.id = c.student_id
  JOIN public.courses co ON co.id = c.course_id
  WHERE c.verification_code = upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'))
    AND c.status IN ('approved', 'revoked')
  LIMIT 1;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE public.activity_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    action text NOT NULL,
    entity_type text,
    entity_id uuid,
    details jsonb,
    ip_address text,
    user_agent text,
    created_at timestamp with time zone DEFAULT now()
);

COMMENT ON TABLE public.activity_logs IS 'Tracks all important actions in the system';

CREATE TABLE public.announcement_reads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    announcement_id uuid NOT NULL,
    user_id uuid NOT NULL,
    read_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.announcements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    message text NOT NULL,
    target_audience text NOT NULL,
    created_by uuid NOT NULL,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    CONSTRAINT announcements_target_audience_check CHECK ((target_audience = ANY (ARRAY['students'::text, 'teachers'::text, 'all'::text])))
);

CREATE TABLE public.assignment_submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lesson_id uuid NOT NULL,
    student_id uuid NOT NULL,
    project_links text[] DEFAULT '{}'::text[],
    description text,
    submitted_at timestamp with time zone DEFAULT now(),
    grade integer,
    feedback text,
    graded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    rubric_scores jsonb,
    CONSTRAINT assignment_submissions_grade_check CHECK (((grade >= 0) AND (grade <= 100)))
);

COMMENT ON TABLE public.assignment_submissions IS 'Submissions for regular assignments (from course_lessons with content_type=assignment)';

COMMENT ON COLUMN public.assignment_submissions.lesson_id IS 'Reference to course_lessons where content_type=assignment';

COMMENT ON COLUMN public.assignment_submissions.project_links IS 'Array of file paths in storage';

CREATE TABLE public.assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    due_date timestamp with time zone,
    max_score integer DEFAULT 100,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.bundle_courses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bundle_id uuid NOT NULL,
    course_id uuid NOT NULL
);

CREATE TABLE public.capstone_projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    instructions text NOT NULL,
    requirements text[],
    due_date timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    file_url text,
    rubric jsonb,
    CONSTRAINT capstone_projects_rubric_valid CHECK (public.is_valid_rubric(rubric))
);

COMMENT ON TABLE public.capstone_projects IS 'Course final capstone projects';

COMMENT ON COLUMN public.capstone_projects.file_url IS 'Optional PDF file URL uploaded by the teacher as the capstone brief';

CREATE TABLE public.capstone_submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    capstone_project_id uuid NOT NULL,
    student_id uuid NOT NULL,
    project_links text[],
    description text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    grade integer,
    feedback text,
    graded_at timestamp with time zone,
    graded_by uuid,
    file_url text,
