);

COMMENT ON TABLE public.capstone_submissions IS 'Student submissions for capstone projects';

COMMENT ON COLUMN public.capstone_submissions.file_url IS 'Optional document file URL uploaded by the student as part of their submission';

CREATE SEQUENCE public.certificate_number_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE public.certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_id uuid NOT NULL,
    course_id uuid NOT NULL,
    certificate_url text,
    status text DEFAULT 'pending'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    completion_date timestamp with time zone DEFAULT now() NOT NULL,
    grade text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    certificate_number text,
    verification_code text,
    issued_at timestamp with time zone,
    issue_source text DEFAULT 'manual'::text NOT NULL,
    capstone_grade integer,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    revoked_reason text,
    CONSTRAINT certificates_issue_source_check CHECK ((issue_source = ANY (ARRAY['manual'::text, 'auto'::text]))),
    CONSTRAINT certificates_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'revoked'::text])))
);

CREATE TABLE public.cohort_join_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cohort_id uuid NOT NULL,
    student_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_track text DEFAULT 'full'::text,
    CONSTRAINT cohort_join_requests_payment_track_check CHECK ((payment_track = ANY (ARRAY['full'::text, 'instalment'::text, 'scholarship'::text]))),
    CONSTRAINT cohort_join_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);

CREATE TABLE public.cohorts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    course_id uuid,
    teacher_id uuid NOT NULL,
    start_date timestamp with time zone,
    end_date timestamp with time zone,
    max_students integer DEFAULT 30,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    price numeric,
    currency text DEFAULT 'RWF'::text,
    requires_payment boolean DEFAULT false NOT NULL,
    instalment_enabled boolean DEFAULT false NOT NULL,
    instalment_count integer DEFAULT 2,
    instalment_deposit_percent numeric DEFAULT 50,
