COMMENT ON COLUMN public.profiles.is_suspended IS 'Whether user account is suspended';

CREATE VIEW public.conversations_with_details WITH (security_invoker='true') AS
 SELECT c.id,
    c.student_id,
    c.teacher_id,
    c.created_at,
    c.updated_at,
    sp.full_name AS student_name,
    sp.avatar_url AS student_avatar,
    tp.full_name AS teacher_name,
    tp.avatar_url AS teacher_avatar,
    ( SELECT dm.message_text
           FROM public.direct_messages dm
          WHERE (dm.conversation_id = c.id)
          ORDER BY dm.created_at DESC
         LIMIT 1) AS last_message,
    ( SELECT dm.created_at
           FROM public.direct_messages dm
          WHERE (dm.conversation_id = c.id)
          ORDER BY dm.created_at DESC
         LIMIT 1) AS last_message_at,
    ( SELECT count(*) AS count
           FROM public.direct_messages dm
          WHERE ((dm.conversation_id = c.id) AND (dm.is_read = false) AND (dm.sender_id <> auth.uid()))) AS unread_count
   FROM ((public.conversations c
     JOIN public.profiles sp ON ((c.student_id = sp.id)))
     JOIN public.profiles tp ON ((c.teacher_id = tp.id)));

