    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    description text,
    discount_type text NOT NULL,
    discount_value numeric NOT NULL,
    currency text DEFAULT 'RWF'::text,
    max_uses integer,
    uses_count integer DEFAULT 0 NOT NULL,
    max_uses_per_user integer DEFAULT 1,
    valid_from timestamp with time zone DEFAULT now(),
    valid_until timestamp with time zone,
    is_active boolean DEFAULT true,
    applies_to text DEFAULT 'all'::text NOT NULL,
    course_id uuid,
    bundle_id uuid,
    min_purchase_amount numeric,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    coupon_type text DEFAULT 'promo'::text NOT NULL,
    CONSTRAINT coupons_applies_to_check CHECK ((applies_to = ANY (ARRAY['all'::text, 'course'::text, 'bundle'::text]))),
    CONSTRAINT coupons_coupon_type_check CHECK ((coupon_type = ANY (ARRAY['promo'::text, 'scholarship'::text, 'early_bird'::text, 'staff'::text, 'referral'::text]))),
    CONSTRAINT coupons_discount_type_check CHECK ((discount_type = ANY (ARRAY['percent'::text, 'fixed'::text]))),
    CONSTRAINT coupons_discount_value_check CHECK ((discount_value > (0)::numeric)),
    CONSTRAINT coupons_percent_max CHECK (((discount_type <> 'percent'::text) OR (discount_value <= (100)::numeric))),
    CONSTRAINT coupons_scope CHECK ((((applies_to = 'all'::text) AND (course_id IS NULL) AND (bundle_id IS NULL)) OR ((applies_to = 'course'::text) AND (course_id IS NOT NULL) AND (bundle_id IS NULL)) OR ((applies_to = 'bundle'::text) AND (bundle_id IS NOT NULL) AND (course_id IS NULL))))
