    instalment_enrollment_id uuid,
    instalment_schedule_id uuid,
    CONSTRAINT payment_target CHECK ((((course_id IS NOT NULL) AND (bundle_id IS NULL)) OR ((course_id IS NULL) AND (bundle_id IS NOT NULL)))),
    CONSTRAINT payments_payment_track_check CHECK ((payment_track = ANY (ARRAY['full'::text, 'instalment'::text, 'scholarship'::text, 'early_bird'::text]))),
    CONSTRAINT payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'success'::text, 'failed'::text])))
);

CREATE TABLE public.quiz_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    quiz_id uuid NOT NULL,
    student_id uuid NOT NULL,
    answers jsonb,
    score integer,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone
);

CREATE TABLE public.quiz_questions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    quiz_id uuid NOT NULL,
    question_text text NOT NULL,
    question_type text NOT NULL,
    options jsonb,
    correct_answer text,
    points integer DEFAULT 1,
    order_index integer DEFAULT 0,
    CONSTRAINT quiz_questions_question_type_check CHECK ((question_type = ANY (ARRAY['multiple_choice'::text, 'true_false'::text, 'short_answer'::text])))
);

CREATE TABLE public.quizzes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    time_limit integer,
    max_score integer DEFAULT 100,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.scheduled_classes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    teacher_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    scheduled_time timestamp with time zone NOT NULL,
    meet_link text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    end_time timestamp with time zone,
    modality text DEFAULT 'online'::text NOT NULL,
    location text,
    cohort_id uuid,
    status text DEFAULT 'scheduled'::text NOT NULL,
    CONSTRAINT scheduled_classes_modality_check CHECK ((modality = ANY (ARRAY['online'::text, 'in_person'::text, 'hybrid'::text]))),
    CONSTRAINT scheduled_classes_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'cancelled'::text])))
);

CREATE TABLE public.scholarship_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    student_id uuid NOT NULL,
    full_name text NOT NULL,
    email text NOT NULL,
    phone text,
    organisation text,
    motivation text NOT NULL,
    income_band text,
    document_url text,
    status text DEFAULT 'pending'::text NOT NULL,
    scholarship_level text,
    discount_percent numeric,
    discount_fixed numeric,
    coupon_id uuid,
    generated_code text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    admin_notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT scholarship_applications_scholarship_level_check CHECK (((scholarship_level IS NULL) OR (scholarship_level = ANY (ARRAY['full'::text, 'partial'::text, 'reduced'::text])))),
    CONSTRAINT scholarship_applications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'redeemed'::text])))
);

CREATE TABLE public.student_instalment_enrollments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_id uuid NOT NULL,
    course_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    cohort_id uuid,
    total_amount numeric NOT NULL,
    currency text DEFAULT 'RWF'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT student_instalment_enrollments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'defaulted'::text, 'cancelled'::text]))),
    CONSTRAINT student_instalment_enrollments_total_amount_check CHECK ((total_amount >= (0)::numeric))
);

CREATE TABLE public.student_lesson_progress (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_id uuid NOT NULL,
    lesson_id uuid NOT NULL,
    is_completed boolean DEFAULT false,
    started_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    last_position integer DEFAULT 0
);

COMMENT ON TABLE public.student_lesson_progress IS 'Track student progress on individual lessons';

CREATE TABLE public.student_quiz_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_id uuid NOT NULL,
    lesson_id uuid NOT NULL,
    answers jsonb NOT NULL,
    score integer NOT NULL,
    total_points integer NOT NULL,
    passed boolean DEFAULT false,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.student_quiz_attempts IS 'Track student quiz attempts and scores with auto-grading';

CREATE VIEW public.student_teachers_with_whatsapp WITH (security_invoker='true') AS
 SELECT DISTINCT p.id AS teacher_id,
    p.full_name AS teacher_name,
    p.avatar_url AS teacher_avatar,
    c.id AS course_id,
    c.title AS course_name,
    c.whatsapp_link,
    ce.student_id
   FROM ((public.profiles p
     JOIN public.courses c ON ((p.id = c.teacher_id)))
     JOIN public.course_enrollments ce ON ((c.id = ce.course_id)))
  WHERE (p.role = 'teacher'::public.user_role);

CREATE TABLE public.submission_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    submission_type text NOT NULL,
    submission_id uuid NOT NULL,
    reviewer_id uuid DEFAULT auth.uid() NOT NULL,
    suggested_grade numeric,
    rubric_scores jsonb,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT submission_reviews_notes_check CHECK (((notes IS NULL) OR (length(notes) <= 4000))),
    CONSTRAINT submission_reviews_submission_type_check CHECK ((submission_type = ANY (ARRAY['assignment'::text, 'capstone'::text]))),
    CONSTRAINT submission_reviews_suggested_grade_check CHECK (((suggested_grade IS NULL) OR ((suggested_grade >= (0)::numeric) AND (suggested_grade <= (100)::numeric))))
);

CREATE TABLE public.system_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key text NOT NULL,
    value jsonb NOT NULL,
    description text,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now()
);

COMMENT ON TABLE public.system_settings IS 'Global system configuration';

CREATE TABLE public.teacher_announcements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    teacher_id uuid NOT NULL,
    course_id uuid,
    title text NOT NULL,
    message text NOT NULL,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE public.testimonials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    student_name text NOT NULL,
    student_image_url text,
    testimonial_text text NOT NULL,
    rating integer DEFAULT 5,
    course_name text,
    is_featured boolean DEFAULT true,
    display_order integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    profession text,
    programs_participated text,
    career_impact text,
    CONSTRAINT testimonials_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);

CREATE TABLE public.tutor_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    course_id uuid NOT NULL,
    lesson_id uuid,
    role text NOT NULL,
    content text NOT NULL,
    model text,
    input_tokens integer,
    output_tokens integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tutor_messages_role_check CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text])))
);

