CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ===== Storage buckets =====

INSERT INTO storage.buckets (id, name, public) VALUES ('certificates', 'certificates', true) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;
INSERT INTO storage.buckets (id, name, public) VALUES ('course-thumbnails', 'course-thumbnails', true) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;
INSERT INTO storage.buckets (id, name, public) VALUES ('exhibition-images', 'exhibition-images', true) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;
INSERT INTO storage.buckets (id, name, public) VALUES ('lesson-files', 'lesson-files', false) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;
INSERT INTO storage.buckets (id, name, public) VALUES ('testimonial-images', 'testimonial-images', true) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;

-- ===== Storage rules =====

DROP POLICY IF EXISTS "Admins can delete certificates" ON storage.objects;
CREATE POLICY "Admins can delete certificates" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'certificates'::text) AND (public.get_user_role(auth.uid()) = 'admin'::text)));
DROP POLICY IF EXISTS "Admins can delete exhibition images" ON storage.objects;
CREATE POLICY "Admins can delete exhibition images" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'exhibition-images'::text) AND public.is_admin(auth.uid())));
DROP POLICY IF EXISTS "Admins can delete testimonial images" ON storage.objects;
CREATE POLICY "Admins can delete testimonial images" ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'testimonial-images'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::public.user_role))))));
DROP POLICY IF EXISTS "Admins can manage certificates" ON storage.objects;
CREATE POLICY "Admins can manage certificates" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'certificates'::text) AND (public.get_user_role(auth.uid()) = 'admin'::text)));
DROP POLICY IF EXISTS "Admins can update exhibition images" ON storage.objects;
CREATE POLICY "Admins can update exhibition images" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'exhibition-images'::text) AND public.is_admin(auth.uid())));
DROP POLICY IF EXISTS "Admins can upload certificates" ON storage.objects;
CREATE POLICY "Admins can upload certificates" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'certificates'::text) AND (public.get_user_role(auth.uid()) = 'admin'::text)));
DROP POLICY IF EXISTS "Admins can upload exhibition images" ON storage.objects;
CREATE POLICY "Admins can upload exhibition images" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'exhibition-images'::text) AND public.is_admin(auth.uid())));
DROP POLICY IF EXISTS "Admins can upload testimonial images" ON storage.objects;
CREATE POLICY "Admins can upload testimonial images" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'testimonial-images'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::public.user_role))))));
DROP POLICY IF EXISTS "Anyone can view certificates" ON storage.objects;
CREATE POLICY "Anyone can view certificates" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'certificates'::text));
DROP POLICY IF EXISTS "Anyone can view course thumbnails" ON storage.objects;
CREATE POLICY "Anyone can view course thumbnails" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'course-thumbnails'::text));
DROP POLICY IF EXISTS "Anyone can view exhibition images" ON storage.objects;
CREATE POLICY "Anyone can view exhibition images" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'exhibition-images'::text));
DROP POLICY IF EXISTS "Anyone can view testimonial images" ON storage.objects;
CREATE POLICY "Anyone can view testimonial images" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'testimonial-images'::text));
DROP POLICY IF EXISTS "Approved teachers and admins upload lesson files" ON storage.objects;
CREATE POLICY "Approved teachers and admins upload lesson files" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'lesson-files'::text) AND (COALESCE((storage.foldername(name))[1], ''::text) <> 'capstone-submissions'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles p
  WHERE ((p.id = auth.uid()) AND ((p.role = 'admin'::public.user_role) OR ((p.role = 'teacher'::public.user_role) AND COALESCE(p.teacher_approved, false))))))));
DROP POLICY IF EXISTS "Facilitators read assigned learners' submission files" ON storage.objects;
CREATE POLICY "Facilitators read assigned learners' submission files" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'lesson-files'::text) AND public.facilitator_can_read_file(name)));
DROP POLICY IF EXISTS "Lesson files follow lesson access" ON storage.objects;
CREATE POLICY "Lesson files follow lesson access" ON storage.objects AS PERMISSIVE FOR SELECT TO anon, authenticated USING (((bucket_id = 'lesson-files'::text) AND ((owner_id = (auth.uid())::text) OR public.can_read_lesson_file(name))));
DROP POLICY IF EXISTS "Students can upload assignment files" ON storage.objects;
CREATE POLICY "Students can upload assignment files" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'lesson-files'::text) AND ((storage.foldername(name))[1] = 'capstone-submissions'::text) AND ((auth.uid())::text = (storage.foldername(name))[3])));
DROP POLICY IF EXISTS "Students can view their uploaded assignment files" ON storage.objects;
CREATE POLICY "Students can view their uploaded assignment files" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'lesson-files'::text) AND (((storage.foldername(name))[1] = 'capstone-submissions'::text) AND ((auth.uid())::text = (storage.foldername(name))[3]))));
DROP POLICY IF EXISTS "Teachers and admins can delete course thumbnails" ON storage.objects;
CREATE POLICY "Teachers and admins can delete course thumbnails" ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'course-thumbnails'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::public.user_role, 'teacher'::public.user_role])))))));
DROP POLICY IF EXISTS "Teachers and admins can update course thumbnails" ON storage.objects;
CREATE POLICY "Teachers and admins can update course thumbnails" ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'course-thumbnails'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::public.user_role, 'teacher'::public.user_role])))))));
DROP POLICY IF EXISTS "Teachers and admins can upload course thumbnails" ON storage.objects;
CREATE POLICY "Teachers and admins can upload course thumbnails" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'course-thumbnails'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::public.user_role, 'teacher'::public.user_role])))))));
DROP POLICY IF EXISTS "Uploader or course teacher can delete lesson files" ON storage.objects;
CREATE POLICY "Uploader or course teacher can delete lesson files" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'lesson-files'::text) AND ((owner_id = (auth.uid())::text) OR public.can_manage_lesson_file(name))));
DROP POLICY IF EXISTS "Uploader or course teacher can replace lesson files" ON storage.objects;
CREATE POLICY "Uploader or course teacher can replace lesson files" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'lesson-files'::text) AND ((owner_id = (auth.uid())::text) OR public.can_manage_lesson_file(name))));

-- ===== Live updates =====

DO $$
DECLARE
  t TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY['announcements', 'direct_messages', 'notifications'] LOOP
    IF to_regclass('public.' || t) IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;

